<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';
require_permission('security.view');$pageTitle='Centro de Seguridad';$user=current_user();$canManage=has_permission('security.manage');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();if(!$canManage){http_response_code(403);exit('Acceso restringido.');}$action=(string)($_POST['action']??'');
 if($action==='save_policy'){
  $passwordStmt=db()->prepare('SELECT password_hash FROM users WHERE id=?');$passwordStmt->execute([(int)$user['id']]);
  if(!password_verify((string)($_POST['policy_current_password']??''),(string)$passwordStmt->fetchColumn())){flash('error','Confirma tu contraseña actual para cambiar las políticas.');redirect('security_center.php');}
  $idle=max(5,min(240,(int)($_POST['session_idle_minutes']??30)));$absolute=max(1,min(72,(int)($_POST['session_absolute_hours']??8)));$min=max(12,min(64,(int)($_POST['password_min_length']??12)));$attempts=max(3,min(10,(int)($_POST['login_max_attempts']??5)));$lock=max(5,min(1440,(int)($_POST['login_lock_minutes']??15)));
  set_setting('session_idle_minutes',(string)$idle);set_setting('session_absolute_hours',(string)$absolute);set_setting('password_min_length',(string)$min);set_setting('login_max_attempts',(string)$attempts);set_setting('login_lock_minutes',(string)$lock);set_setting('security_alert_email',trim((string)($_POST['security_alert_email']??'info@socrates.la')));set_setting('force_admin_totp',isset($_POST['force_admin_totp'])?'1':'0');
  crm_security_audit('security_policy_updated','critical','Políticas de seguridad actualizadas');flash('success','Políticas de seguridad guardadas.');redirect('security_center.php');
 }
 if($action==='revoke_session'){$id=(int)($_POST['session_id']??0);db()->prepare('UPDATE user_sessions SET is_revoked=1,revoked_at=NOW() WHERE id=?')->execute([$id]);crm_security_audit('session_revoked','warning','Sesión revocada #'.$id,'session',$id);flash('success','Sesión cerrada.');redirect('security_center.php');}
 if($action==='revoke_others'){crm_revoke_user_sessions((int)$user['id'],(string)($_SESSION['crm_session_token']??''));flash('success','Se cerraron las demás sesiones de tu usuario.');redirect('security_center.php');}
 if($action==='integrity_baseline'){$result=crm_integrity_save();flash('success','Línea base creada con '.$result['count'].' archivos.');redirect('security_center.php');}
 if($action==='create_backup'){
  $stmt=db()->prepare('SELECT password_hash FROM users WHERE id=?');$stmt->execute([(int)$user['id']]);
  if(!password_verify((string)($_POST['current_password']??''),(string)$stmt->fetchColumn()))flash('error','La contraseña actual no es correcta.');
  else{$backup=crm_database_backup();flash('success','Respaldo cifrado creado: '.$backup['name']);}
  redirect('security_center.php');
 }
}
$score=crm_security_score();$integrity=crm_integrity_check();$backups=crm_backup_files();
$logs=[];$sessions=[];$loginFailures=[];
if(db_table_exists('security_audit_logs')){$logs=db()->query("SELECT l.*,u.name user_name,u.email user_email FROM security_audit_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 80")->fetchAll();}
if(db_table_exists('user_sessions')){$sessions=db()->query("SELECT s.*,u.name,u.email FROM user_sessions s JOIN users u ON u.id=s.user_id WHERE s.is_revoked=0 AND (s.expires_at IS NULL OR s.expires_at>NOW()) ORDER BY s.last_activity_at DESC LIMIT 100")->fetchAll();}
if(db_table_exists('login_attempts')){$loginFailures=db()->query("SELECT ip_address,COUNT(*) attempts,MAX(attempted_at) last_attempt FROM login_attempts WHERE success=0 AND attempted_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) GROUP BY ip_address ORDER BY attempts DESC LIMIT 10")->fetchAll();}
$admins=[];try{$admins=db()->query("SELECT id,name,email,two_factor_enabled,two_factor_method,last_login_at,last_login_ip FROM users WHERE role='admin' AND is_active=1 ORDER BY name")->fetchAll();}catch(Throwable){}
require __DIR__.'/includes/header.php';
?>
<div class="project-hero compact"><div><span class="eyebrow">SEGURIDAD & AUDITORÍA</span><h2>Centro de Seguridad</h2><p>Una lectura simple de accesos, 2FA, sesiones, integridad, respaldos y actividad sensible.</p></div><a class="btn btn-secondary" href="security_2fa.php"><?=crm_icon('shield')?> CONFIGURAR MI 2FA</a></div>
<div class="security-kpis"><div class="security-kpi"><span class="sec-icon"><?=crm_icon('shield')?></span><small>Puntaje</small><strong><?=e($score['score'])?>/100</strong><span><?=$score['score']>=85?'Protección alta':($score['score']>=65?'Mejorable':'Requiere atención')?></span></div><div class="security-kpi"><span class="sec-icon"><?=crm_icon('users')?></span><small>Sesiones activas</small><strong><?=count($sessions)?></strong><span>Dispositivos conectados</span></div><div class="security-kpi"><span class="sec-icon"><?=crm_icon('risk')?></span><small>Intentos fallidos</small><strong><?=array_sum(array_map(fn($x)=>(int)$x['attempts'],$loginFailures))?></strong><span>Últimas 24 horas</span></div><div class="security-kpi"><span class="sec-icon"><?=crm_icon('shield')?></span><small>Integridad</small><strong><?=$integrity['baseline']?($integrity['ok']?'OK':'REVISAR'):'PENDIENTE'?></strong><span>Archivos del sistema</span></div><div class="security-kpi"><span class="sec-icon"><?=crm_icon('download')?></span><small>Respaldos</small><strong><?=count($backups)?></strong><span>Copias cifradas disponibles</span></div></div>
<div class="security-section-grid"><section class="security-card"><div class="security-card-head"><div><strong>Estado de controles</strong><small class="table-sub">Qué está bien y qué requiere acción.</small></div></div><div class="security-card-body security-list"><?php foreach($score['checks'] as$check):?><div class="security-list-row <?=$check['ok']?'is-ok':'is-warning'?>"><span class="sec-status-icon"><?=$check['ok']?crm_icon('shield'):crm_icon('risk')?></span><div><strong><?=e($check['label'])?></strong><small class="table-sub"><?=$check['ok']?'Correcto':'Requiere atención'?></small></div><span class="badge <?=$check['ok']?'badge-green':'badge-orange'?>"><?=$check['ok']?'OK':'REVISAR'?></span></div><?php endforeach;?></div></section>
<section class="security-card"><div class="security-card-head"><div><strong>Administradores y 2FA</strong><small class="table-sub">TOTP recomendado para cuentas privilegiadas.</small></div></div><div class="security-card-body security-list"><?php foreach($admins as$admin):?><div class="security-list-row"><span class="sec-dot"><?=e(crm_upper(crm_substr((string)$admin['name'],0,1)))?></span><div><strong><?=e($admin['name'])?></strong><small class="table-sub"><?=e($admin['email'])?></small></div><span class="badge <?=($admin['two_factor_enabled']&&$admin['two_factor_method']==='totp')?'badge-green':'badge-orange'?>"><?=($admin['two_factor_enabled']&&$admin['two_factor_method']==='totp')?'TOTP ACTIVO':'REVISAR 2FA'?></span></div><?php endforeach;?></div></section></div>
<div class="security-section-grid"><section class="security-card"><div class="security-card-head"><div><strong>Integridad de archivos</strong><small class="table-sub">Detecta archivos modificados, faltantes o nuevos.</small></div><span class="badge <?=$integrity['ok']?'badge-green':'badge-orange'?>"><?=$integrity['baseline']?($integrity['ok']?'SIN CAMBIOS':'REVISAR'):'SIN LÍNEA BASE'?></span></div><div class="security-card-body"><?php if($integrity['baseline']):?><div class="details-grid" style="grid-template-columns:repeat(3,1fr)"><div class="detail"><small>Modificados</small><strong><?=count($integrity['changed'])?></strong></div><div class="detail"><small>Faltantes</small><strong><?=count($integrity['missing'])?></strong></div><div class="detail"><small>Nuevos</small><strong><?=count($integrity['new'])?></strong></div></div><?php else:?><p class="muted">Crea una línea base cuando confirmes que la versión instalada funciona correctamente.</p><?php endif;?><?php if($canManage):?><form method="post" style="margin-top:14px" onsubmit="return confirm('¿Reemplazar la línea base de integridad?')"><?=csrf_field()?><button class="btn btn-secondary" name="action" value="integrity_baseline">CREAR / RENOVAR LÍNEA BASE</button></form><?php endif;?></div></section>
<section class="security-card"><div class="security-card-head"><div><strong>Respaldos cifrados</strong><small class="table-sub">Descárgalos y guárdalos fuera del servidor.</small></div></div><div class="security-card-body"><?php if($canManage):?><form method="post" class="form-grid"><?=csrf_field()?><label>Confirma tu contraseña<input type="password" name="current_password" required></label><div class="form-actions"><button class="btn btn-primary" name="action" value="create_backup">CREAR RESPALDO</button></div></form><?php endif;?><?php if($backups):?><div class="security-list" style="margin-top:12px"><?php foreach(array_slice($backups,0,4) as$b):?><div class="security-list-row"><span class="sec-dot"><?=crm_icon('download')?></span><div><strong><?=e($b['name'])?></strong><small class="table-sub"><?=e(format_date_time($b['modified_at']))?> · <?=e(number_format($b['size']/1024,1,',','.'))?> KB</small></div><form method="post" action="security_backup_download.php"><?=csrf_field()?><input type="hidden" name="file" value="<?=e($b['name'])?>"><button class="icon-action" title="Descargar"><?=crm_icon('download')?></button></form></div><?php endforeach;?></div><?php endif;?></div></section></div>
<?php if($canManage):?><section class="panel"><div class="panel-header"><div><h2>Políticas de acceso</h2><span class="table-sub">Define límites de sesión, contraseñas y bloqueos.</span></div></div><form method="post" class="panel-body form-grid three"><?=csrf_field()?><label>Inactividad máxima (min)<input type="number" min="5" max="240" name="session_idle_minutes" value="<?=e(setting('session_idle_minutes','30'))?>"></label><label>Duración máxima (horas)<input type="number" min="1" max="72" name="session_absolute_hours" value="<?=e(setting('session_absolute_hours','8'))?>"></label><label>Longitud mínima contraseña<input type="number" min="12" max="64" name="password_min_length" value="<?=e(setting('password_min_length','12'))?>"></label><label>Intentos antes de bloquear<input type="number" min="3" max="10" name="login_max_attempts" value="<?=e(setting('login_max_attempts','5'))?>"></label><label>Bloqueo (minutos)<input type="number" min="5" max="1440" name="login_lock_minutes" value="<?=e(setting('login_lock_minutes','15'))?>"></label><label>Email de seguridad<input type="email" name="security_alert_email" value="<?=e(setting('security_alert_email','info@socrates.la'))?>"></label><label>Confirma contraseña<input type="password" name="policy_current_password" required></label><label class="checkbox-row full"><input type="checkbox" name="force_admin_totp" value="1" <?=setting('force_admin_totp','0')==='1'?'checked':''?>> Exigir TOTP a administradores globales</label><div class="full form-actions"><button class="btn btn-primary" name="action" value="save_policy">GUARDAR POLÍTICAS</button></div></form></section><?php endif;?>
<section class="panel"><div class="panel-header"><div><h2>Sesiones activas</h2><span class="table-sub">Una tarjeta por dispositivo conectado. Puedes cerrar sesiones remotas.</span></div><?php if($canManage):?><form method="post"><?=csrf_field()?><button class="btn btn-light" name="action" value="revoke_others">CERRAR MIS OTRAS SESIONES</button></form><?php endif;?></div><div class="panel-body security-list"><?php foreach($sessions as$s):?><div class="security-list-row"><span class="sec-dot"><?=crm_icon('users')?></span><div><strong><?=e($s['name'])?> · <?=e($s['ip_address'])?></strong><small class="table-sub"><?=e(crm_strimwidth((string)$s['user_agent'],90))?> · última actividad <?=e(format_date_time($s['last_activity_at']??null))?></small></div><?php if($canManage&&(string)$s['session_hash']!==(string)($_SESSION['crm_session_token']??'')):?><form method="post"><?=csrf_field()?><input type="hidden" name="session_id" value="<?=$s['id']?>"><button class="btn btn-danger btn-small" name="action" value="revoke_session">CERRAR</button></form><?php else:?><span class="badge badge-green">ACTUAL</span><?php endif;?></div><?php endforeach;?></div></section>
<section class="panel"><div class="panel-header"><div><h2>Auditoría de seguridad</h2><span class="table-sub">Eventos recientes. Haz clic en una fila mentalmente como registro técnico: fecha, evento, usuario, IP y detalle.</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Severidad</th><th>Evento</th><th>Usuario</th><th>IP</th><th>Detalle</th></tr></thead><tbody><?php foreach($logs as$log):?><tr><td><?=e(format_date_time($log['created_at']))?></td><td><span class="badge badge-<?=$log['severity']==='critical'?'red':($log['severity']==='warning'?'orange':'blue')?>"><?=e(crm_upper($log['severity']))?></span></td><td><strong><?=e($log['event'])?></strong></td><td><?=e($log['user_name']??'Sistema')?></td><td><code><?=e($log['ip_address'])?></code></td><td><?=e(crm_strimwidth((string)$log['details'],110))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/includes/footer.php';?>
